import java.util.*;

class Solution {
  public boolean makesquare(int[] matchsticks) {
    int sum = 0;
    for (int m : matchsticks) sum += m;
    if (sum % 4 != 0) return false;
    Integer[] sticks = Arrays.stream(matchsticks).boxed().sorted(Collections.reverseOrder()).toArray(Integer[]::new);
    return place(sticks, 0, new int[4], sum / 4);
  }

  private boolean place(Integer[] sticks, int i, int[] sides, int target) {
    if (i == sticks.length) return sides[0] == target && sides[1] == target && sides[2] == target;
    for (int s = 0; s < 4; s++) {
      if (sides[s] + sticks[i] > target) continue;
      boolean repeat = false; // sides with equal length are interchangeable
      for (int t = 0; t < s; t++) if (sides[t] == sides[s]) repeat = true;
      if (repeat) continue;
      sides[s] += sticks[i];
      if (place(sticks, i + 1, sides, target)) return true;
      sides[s] -= sticks[i];
    }
    return false;
  }
}
